#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Puts the hosted demo live (#140, ADR-0021):
#   bash infra/provision-wizard.sh
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=11

# Run from the repo root. Two git-ignored files:
#   .env.production  the VM's .env (every AGENTPAY_ hosted setting), copied to the VM
#   .env.provision   this wizard's own notes: the VM's address, SSH key and the live URLs
# The Demo Tenant's keys go into the local .env, for `python -m demo`.
cd "$(dirname "$0")/.."
PROD=.env.production
NOTES=.env.provision
REPO_URL="https://github.com/karthikraoofficial/agentpay-guard.git"
COMPOSE="docker compose --env-file .env -f infra/docker-compose.yml -f infra/docker-compose.prod.yml"

# Values go to one of three files; ENV_FILE picks which for each ask and write.
note_ask()    { ENV_FILE=$NOTES ask "$@"; }
note_write()  { ENV_FILE=$NOTES write_env "$@"; }
prod_ask()    { ENV_FILE=$PROD ask "$@"; }
prod_secret() { ENV_FILE=$PROD ask_secret "$@"; }
prod_write()  { ENV_FILE=$PROD write_env "$@"; }

# vm CMD runs CMD on the VM over SSH.
vm() { ssh -i "$SSH_KEY" -o StrictHostKeyChecking=accept-new -o ConnectTimeout=15 "$VM_USER@$VM_IP" "$@"; }

if [[ ! -f "$PROD" ]]; then
  cp .env.production.example "$PROD"
  chmod 600 "$PROD"
fi

banner "AgentPay Guard: put the hosted demo live (#140)"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Oracle Cloud: create the Always Free VM"
say "One Always Free Ampere (ARM) VM runs the whole stack (ADR-0021)."
note "Always Free Ampere is 2 OCPUs and 12 GB in total. Oracle may reclaim an instance"
note "whose CPU, network and memory all stay under 20% for 7 days."
open_url "https://cloud.oracle.com/compute/instances/create"
step "Sign in (or sign up; a card is asked for but Always Free isn't charged)."
step "Name: agentpay-guard. Use your home region: Always Free only counts there."
step "Image and shape → Change image → Canonical Ubuntu 24.04 (the aarch64 build)."
step "Change shape → Ampere → VM.Standard.A1.Flex → 2 OCPUs, 12 GB memory."
step "Networking → Primary network: Create new virtual cloud network."
step "Subnet: Create new public subnet (a private subnet greys out the public IP switch)."
step "Turn on 'Automatically assign public IPv4 address'."
step "Add SSH keys → Generate a key pair → Save private key (or paste your own public key)."
step "Create. Wait for the state RUNNING, then copy the Public IP address."
note "If it says 'Out of capacity', try another availability domain, or again later."
note_ask VM_IP "Paste the VM's public IP:"
note_write VM_IP "$VM_IP"
note_ask SSH_KEY "Path to the SSH private key you saved (e.g. ~/Downloads/ssh-key.key):"
SSH_KEY="${SSH_KEY/#\~/$HOME}"
note_write SSH_KEY "$SSH_KEY"
note_ask VM_USER "SSH user (Enter for ubuntu):"
VM_USER="${VM_USER:-ubuntu}"
note_write VM_USER "$VM_USER"

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Connect to the VM"
chmod 600 "$SSH_KEY" 2>/dev/null || true
say "Checking SSH to $VM_USER@$VM_IP …"
until vm true; do
  warn "SSH didn't connect. A new VM can take a minute or two to accept SSH."
  pause "Press Enter to try again (Ctrl-C to stop)"
done
printf '  %s✓ connected%s\n' "$GREEN" "$RESET"
pause

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Open ports 80 and 443"
say "Two firewalls must both let HTTP and HTTPS in: Oracle's security list, and the"
say "VM's own iptables rules (Oracle's Ubuntu images reject everything but SSH)."
open_url "https://cloud.oracle.com/networking/vcns"
step "Open the VCN made with the VM → Subnets → the public subnet → its Default Security List."
step "Add Ingress Rules: Source CIDR 0.0.0.0/0, IP protocol TCP, Destination port 80."
step "Add another: Source CIDR 0.0.0.0/0, TCP, Destination port 443."
pause "Press Enter once both rules are saved"
if confirm "Insert iptables ACCEPT rules for 80 and 443 on the VM, and save them?"; then
  vm 'set -e
    for port in 443 80; do
      if ! sudo iptables -C INPUT -p tcp --dport "$port" -m state --state NEW -j ACCEPT 2>/dev/null; then
        at=$(sudo iptables -L INPUT --line-numbers | awk "/REJECT/ {print \$1; exit}")
        sudo iptables -I INPUT "${at:-1}" -p tcp --dport "$port" -m state --state NEW -j ACCEPT
      fi
    done
    sudo netfilter-persistent save >/dev/null'
  printf '  %s✓ ports 80 and 443 open on the VM%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("iptables rules for ports 80 and 443 on the VM")
fi
pause

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Install Docker and fetch the code"
say "Installs Docker from get.docker.com and clones $REPO_URL on the VM."
if confirm "Install Docker and clone the repo on the VM?"; then
  vm 'set -e
    if ! command -v docker >/dev/null; then
      curl -fsSL https://get.docker.com | sudo sh
      sudo usermod -aG docker "$USER"
    fi
    if [ -d agentpay-guard ]; then git -C agentpay-guard pull --ff-only
    else git clone '"$REPO_URL"' agentpay-guard; fi'
  printf '  %s✓ Docker installed and code fetched%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Docker and the code on the VM")
fi
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Langfuse: a project for the traces"
open_url "https://cloud.langfuse.com"
step "Sign in (Hobby is free) and create an organization and a project: agentpay-guard."
step "Project Settings → API Keys → Create new API keys."
note "Use the region you signed up in: EU is cloud.langfuse.com, US is us.cloud.langfuse.com."
prod_ask AGENTPAY_LANGFUSE_PUBLIC_KEY "Paste the public key (pk-lf-…):"
prod_secret AGENTPAY_LANGFUSE_SECRET_KEY "Paste the secret key (sk-lf-…, hidden):"
prod_ask AGENTPAY_LANGFUSE_HOST "Langfuse host (Enter keeps it; EU https://cloud.langfuse.com):"
AGENTPAY_LANGFUSE_HOST="${AGENTPAY_LANGFUSE_HOST:-https://cloud.langfuse.com}"
prod_write AGENTPAY_LANGFUSE_PUBLIC_KEY "$AGENTPAY_LANGFUSE_PUBLIC_KEY"
prod_write AGENTPAY_LANGFUSE_SECRET_KEY "$AGENTPAY_LANGFUSE_SECRET_KEY"
prod_write AGENTPAY_LANGFUSE_HOST "$AGENTPAY_LANGFUSE_HOST"
pause

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Anthropic: a key for the hosted demo"
say "The demo's only cost. The Model spend cap holds each Tenant to 200 Intent checks"
say "and 20 dispute narratives a day (ADR-0020)."
open_url "https://console.anthropic.com/settings/keys"
step "Create Key → name it agentpay-guard-demo → copy it."
step "Check Plans & Billing has credit; without it every Intent check fails closed to unknown."
note "Optional: Limits → set a monthly spend limit for the workspace."
prod_secret AGENTPAY_ANTHROPIC_API_KEY "Paste the key (sk-ant-…, hidden):"
prod_write AGENTPAY_ANTHROPIC_API_KEY "$AGENTPAY_ANTHROPIC_API_KEY"
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
API_HOST="api.${VM_IP//./-}.sslip.io"
stage "Vercel: the web app"
say "The API will be at https://$API_HOST (sslip.io maps that name to $VM_IP)."
open_url "https://vercel.com/new"
step "Import the GitHub repo karthikraoofficial/agentpay-guard (Hobby is free)."
step "Root Directory: web. Framework: Next.js (web/vercel.json sets the build)."
step "Environment Variables: NEXT_PUBLIC_API_URL = https://$API_HOST"
step "Deploy. When it's live, copy the production domain (https://….vercel.app)."
note "The Ops console reads ../evals/report.json at build time. If /ops shows 'Sample data',"
note "turn on Settings → Build → 'Include files outside the root directory' and redeploy."
note_ask WEB_URL "Paste the Vercel URL (https://…, no trailing slash):"
WEB_URL="${WEB_URL%/}"
note_write WEB_URL "$WEB_URL"
note_write API_URL "https://$API_HOST"
pause

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Write the VM's .env"
say "Fills $PROD from .env.production.example and copies it to the VM as .env."
prod_write AGENTPAY_API_HOST "$API_HOST"
prod_write AGENTPAY_WEB_ORIGIN "$WEB_URL"
# Generated here, never typed or shown. The Postgres password only takes effect when its
# volume is first made, so an existing one is kept.
password=$(ENV_FILE=$PROD _existing AGENTPAY_POSTGRES_PASSWORD || true)
if [[ -z "$password" || "$password" == replace-* ]]; then
  prod_write AGENTPAY_POSTGRES_PASSWORD "$(openssl rand -hex 24)"
else
  note "keeping the existing Postgres password"
fi
fernet=$(ENV_FILE=$PROD _existing AGENTPAY_WEBHOOK_ENCRYPTION_KEY || true)
if [[ -z "$fernet" || "$fernet" == replace-* ]]; then
  prod_write AGENTPAY_WEBHOOK_ENCRYPTION_KEY "$(openssl rand -base64 32 | tr '+/' '-_')"
fi
unset password fernet
if grep -qE "^[A-Z_]+=['\"]?(replace-|sk-ant-replace|pk-lf-replace|sk-lf-replace)" "$PROD"; then
  warn "some placeholders are left in $PROD:"
  grep -oE "^[A-Z_]+=['\"]?(replace-|sk-ant-replace|pk-lf-replace|sk-lf-replace)" "$PROD" | cut -d= -f1 | sed 's/^/    /'
  pause "Fix them in $PROD, then press Enter"
fi
scp -i "$SSH_KEY" -q "$PROD" "$VM_USER@$VM_IP:agentpay-guard/.env"
vm 'chmod 600 agentpay-guard/.env'
printf '  %s✓ copied%s %s → %s:agentpay-guard/.env\n' "$GREEN" "$RESET" "$PROD" "$VM_IP"
pause

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Start the stack"
say "Builds the image on the VM and starts Postgres, Temporal, the collector, the"
say "migration, the API, the worker and Caddy. The first build takes a few minutes."
if confirm "Start (or update) the stack on the VM now?"; then
  vm "cd agentpay-guard && git pull --ff-only && $COMPOSE up -d --build"
fi
say "Waiting for https://$API_HOST/healthz (Caddy gets its certificate on the first request)…"
healthy=""
for _ in $(seq 1 60); do
  if curl -fsS --max-time 10 "https://$API_HOST/healthz" >/dev/null 2>&1; then healthy=yes; break; fi
  sleep 5
done
if [[ -n "$healthy" ]]; then
  printf '  %s✓ https://%s/healthz answers%s\n' "$GREEN" "$API_HOST" "$RESET"
else
  warn "no answer yet. On the VM: cd agentpay-guard && $COMPOSE logs caddy api"
  SKIPPED+=("https://$API_HOST/healthz didn't answer within 5 minutes")
fi
pause

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Create the Demo Tenant"
if [[ -n "$(ENV_FILE=.env _existing AGENTPAY_DEMO_AGENT_KEY || true)" ]] && \
   ! confirm "The local .env already has Demo Tenant keys. Create a new Demo Tenant anyway?"; then
  note "keeping the existing Demo Tenant keys"
elif confirm "Create the Demo Tenant on the hosted stack?"; then
  created=$(vm "cd agentpay-guard && $COMPOSE exec -T api python -m api.admin create-tenant Demo")
  tenant_id=$(printf '%s\n' "$created" | sed -n 's/^tenant_id: //p')
  agent_key=$(printf '%s\n' "$created" | sed -n 's/^agent_key ([^)]*): //p')
  tenant_key=$(printf '%s\n' "$created" | sed -n 's/^tenant_key ([^)]*): //p')
  if [[ -z "$agent_key" || -z "$tenant_key" ]]; then
    warn "couldn't read the keys from create-tenant's output; run it by hand on the VM"
    SKIPPED+=("Demo Tenant keys in .env")
  else
    note_write DEMO_TENANT_ID "$tenant_id"
    ENV_FILE=.env write_env AGENTPAY_DEMO_AGENT_KEY "$agent_key"
    ENV_FILE=.env write_env AGENTPAY_DEMO_TENANT_KEY "$tenant_key"
    say "Demo Tenant $tenant_id. Its keys are in your local .env and were not shown."
  fi
  unset created agent_key tenant_key
fi
pause

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Check it's live"
say "Demo journey 1 against the hosted API (no model call):"
if uv run python -m demo --base-url "https://$API_HOST" --journey 1; then
  printf '  %s✓ journey 1 ran on the hosted demo%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("demo journey 1 against https://$API_HOST")
fi
open_url "$WEB_URL/ops"
step "The Ops console should show 203 Decision cases (not 'Sample data')."
open_url "$AGENTPAY_LANGFUSE_HOST"
step "Langfuse → your project → Tracing: a 'decision' trace from journey 1 should appear within a minute."
if confirm "Do you see the decision trace in Langfuse?"; then
  note_write LANGFUSE_TRACES_SEEN "yes"
else
  SKIPPED+=("Langfuse traces: on the VM, $COMPOSE logs otel-collector")
fi
say "Live: API https://$API_HOST · web $WEB_URL"
note "Tell Claude these URLs so the README gets them (ticket #140)."
pause

finish
}

run_wizard "$@"; exit
